import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import api from '../services/api';

const Dashboard = () => {
  const { user } = useContext(AuthContext);
  const [myProducts, setMyProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchData = async () => {
    try {
      const catRes = await api.get('categories/');
      setCategories(catRes.data.results || catRes.data);

      const prodRes = await api.get('products/');
      const filtered = (prodRes.data.results || prodRes.data).filter(
        (p) => p.owner?.username === user?.username
      );
      setMyProducts(filtered);
    } catch (err) {
      console.error('Ошибка загрузки данных', err);
    }
  };

  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  const handleCreateProduct = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await api.post('products/', {
        title,
        description,
        price,
        category: category ? Number(category) : null,
      });
      setTitle('');
      setDescription('');
      setPrice('');
      setCategory('');
      fetchData();
      alert('Товар успешно создан!');
    } catch (err) {
      console.error('Ошибка создания товара', err);
      alert('Не удалось создать товар');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteProduct = async (id) => {
    if (window.confirm('Вы уверены, что хотите удалить этот товар?')) {
      try {
        await api.delete(`products/${id}/`);
        fetchData();
      } catch (err) {
        console.error('Ошибка удаления', err);
        alert('Не удалось удалить товар');
      }
    }
  };

  return (
    <div style={{ maxWidth: '1000px', margin: '40px auto', padding: '30px' }}>
      <h2 style={{ fontSize: '28px', color: '#1a1a1a', marginBottom: '20px' }}>Панель управления продавца</h2>
      
      <div style={{ background: '#fdfbf7', padding: '20px', borderRadius: '14px', marginBottom: '30px', border: '1px solid #faedcd' }}>
        <p style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#444' }}>Добро пожаловать, <strong style={{ color: '#1a1a1a' }}>{user?.username}</strong>!</p>
        <p style={{ margin: 0, color: '#8c7a6b', fontSize: '14px' }}>Роль в системе: <em style={{ color: '#D97706', fontWeight: 'bold' }}>{user?.role}</em></p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px' }}>
        {/* Форма создания товара */}
        <div style={{ background: '#fff', padding: '30px', borderRadius: '16px', border: '1px solid #eaeaea', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>
          <h3 style={{ marginTop: 0, marginBottom: '20px', fontSize: '20px', color: '#1a1a1a' }}>Добавить новый товар</h3>
          <form onSubmit={handleCreateProduct} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            <div>
              <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>Название:</label>
              <input 
                type="text" 
                value={title} 
                onChange={(e) => setTitle(e.target.value)} 
                required 
                style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', outline: 'none' }}
                onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                onBlur={(e) => e.target.style.borderColor = '#ced4da'}
              />
            </div>
            <div>
              <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>Описание:</label>
              <textarea 
                value={description} 
                onChange={(e) => setDescription(e.target.value)} 
                required 
                style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', minHeight: '80px', outline: 'none' }}
                onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                onBlur={(e) => e.target.style.borderColor = '#ced4da'}
              />
            </div>
            <div>
              <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>Цена (₾):</label>
              <input 
                type="number" 
                step="0.01" 
                value={price} 
                onChange={(e) => setPrice(e.target.value)} 
                required 
                style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', outline: 'none' }}
                onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                onBlur={(e) => e.target.style.borderColor = '#ced4da'}
              />
            </div>
            <div>
              <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>Категория:</label>
              <select 
                value={category} 
                onChange={(e) => setCategory(e.target.value)}
                style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', background: '#fff', outline: 'none' }}
              >
                <option value="">Выберите категорию</option>
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>{cat.name}</option>
                ))}
              </select>
            </div>
            <button 
              type="submit" 
              disabled={loading}
              style={{ 
                background: '#F59E0B', 
                color: '#1a1a1a', 
                border: 'none', 
                padding: '12px', 
                borderRadius: '8px', 
                fontWeight: 'bold', 
                fontSize: '15px', 
                cursor: 'pointer',
                marginTop: '10px',
                transition: 'background 0.2s'
              }}
              onMouseEnter={(e) => e.target.style.background = '#E08E0B'}
              onMouseLeave={(e) => e.target.style.background = '#F59E0B'}
            >
              {loading ? 'Создание...' : 'Опубликовать товар'}
            </button>
          </form>
        </div>

        {/* Список товаров текущего пользователя */}
        <div>
          <h3 style={{ marginTop: 0, marginBottom: '20px', fontSize: '20px', color: '#1a1a1a' }}>Мои товары</h3>
          {myProducts.length > 0 ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              {myProducts.map((prod) => (
                <div key={prod.id} style={{ background: '#fff', padding: '20px', borderRadius: '14px', border: '1px solid #eaeaea', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <h4 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1a1a1a' }}>{prod.title}</h4>
                    <p style={{ margin: 0, color: '#16a34a', fontWeight: 'bold', fontSize: '15px' }}>{prod.price} ₾</p>
                  </div>
                  <button 
                    onClick={() => handleDeleteProduct(prod.id)}
                    style={{ background: '#fee2e2', color: '#dc2626', border: 'none', padding: '8px 14px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer', transition: 'background 0.2s' }}
                    onMouseEnter={(e) => e.target.style.background = '#fecaca'}
                    onMouseLeave={(e) => e.target.style.background = '#fee2e2'}
                  >
                    Удалить
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <div style={{ background: '#fff', padding: '30px', borderRadius: '16px', border: '1px solid #eaeaea', textAlign: 'center', color: '#888' }}>
              <p style={{ margin: 0 }}>У вас пока нет добавленных товаров.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
